const POTIONS={};
for(const [kind,label,color,values]of [['hp','HP','#dc6c69',[.25,.45,.7]],['mp','MP','#65aee8',[25,55,100]],['sp','SP','#80c887',[35,70,140]]])for(let i=0;i<3;i++)POTIONS[kind+i]={name:label+'ポーション・'+['小','中','大'][i],kind,color,value:values[i],price:[30,120,420][i],cool:[12,18,25][i],desc:label+'を'+(kind==='hp'?values[i]*100+'%（最大HP基準）':values[i])+'回復'};
for(const [id,name,color,price,value,desc]of [['attack','猛攻薬','#ed9a66',300,20,'攻撃力 +20%'],['guard','鉄壁薬','#a2becb',280,15,'ダメージ軽減 +15ポイント'],['speed','疾走薬','#83d8d2',220,25,'移動速度 +25ポイント'],['crit','集中薬','#e9ce78',350,12,'会心率 +12ポイント'],['spell','霊薬','#c6a1eb',320,25,'魔法ダメージ +25ポイント'],['stamina','活力薬','#a7d979',220,8,'SP自然回復 +8/秒']])POTIONS[id]={name,kind:'buff',color,price,value,cool:45,duration:30,desc:desc+'（30秒）'};
function ensurePotions(){if(!p)return;if(!p.potions){p.potions={hp0:Math.min(3,Math.max(0,p.flasks||0))};p.potionSlots=['hp0','mp0','sp0'];p.potionCooldowns={};p.potionBuffs={};}p.potionSlots??=['hp0','mp0','sp0'];p.potionCooldowns??={};p.potionBuffs??={};}
const potionValidateBase=validateSave;validateSave=data=>{const out=potionValidateBase(data);if(data.p.potions!==undefined){for(const field of ['potions','potionCooldowns','potionBuffs']){const src=data.p[field]||{};if(typeof src!=='object'||Array.isArray(src))throw Error('ポーション情報が不正です');out.p[field]={};for(const [id,n]of Object.entries(src)){if(!Object.hasOwn(POTIONS,id)||!Number.isFinite(n)||n<0||n>(field==='potions'?9999:field==='potionCooldowns'?POTIONS[id].cool:POTIONS[id].duration||0)||field==='potions'&&!Number.isInteger(n))throw Error('ポーションの個数・時間が不正です');out.p[field][id]=n;}}if(!Array.isArray(data.p.potionSlots)||data.p.potionSlots.length!==3||data.p.potionSlots.some(id=>!Object.hasOwn(POTIONS,id)))throw Error('ポーション枠が不正です');out.p.potionSlots=[...data.p.potionSlots];}return out;};
function potionBonus(id){return p?.potionBuffs?.[id]>0?POTIONS[id].value:0;}
const potionStatBase=stat;stat=key=>potionStatBase(key)+(['guard','speed','crit','spell'].includes(key)?potionBonus(key):0);
const potionDamageBase=damage;damage=()=>potionDamageBase()*(1+potionBonus('attack')/100);
const potionRegenBase=staminaRegen;staminaRegen=()=>potionRegenBase()+potionBonus('stamina');
function potionPhoenix(slot){const id=p.potionSlots[slot];return POTIONS[id].kind==='hp'&&!(p.potions[id]>0)&&hasStarBoon(namedBoonIndices.Phe);}
function drinkPotion(slot=0){if(!started||paused||dead||!p||p.hp<=0||!Number.isInteger(slot)||slot<0||slot>2)return false;ensurePotions();const id=p.potionSlots[slot],def=POTIONS[id];if((p.potionCooldowns[id]||0)>0)return false;
 if(!(p.potions[id]>0)){if(!potionPhoenix(slot)||p.hp>maxhp()*.5||p.ultimate<50||phoenixCooldown>0){say('ポーションがありません · 村のショップで購入できます');return false;}syncNamedBoons();if(!worldTransaction(()=>{p.ultimate-=50;p.hp=Math.min(maxhp(),p.hp+maxhp()*.25);}))return false;phoenixCooldown=8;phoenixPulse=.65;playSound('heal',p.x,p.y);return true;}
 const cup=def.kind==='hp'&&p.hp>=maxhp()&&hasStarBoon(namedBoonIndices.Crt),resource=cup?'mp':def.kind,max=resource==='hp'?maxhp():resource==='mp'?100:maxsp();if(def.kind!=='buff'&&p[resource]>=max)return false;
 if(!worldTransaction(()=>{p.potions[id]--;p.potionCooldowns[id]=def.cool;if(def.kind==='buff')p.potionBuffs[id]=def.duration;else {let amount=cup?60:def.kind==='hp'?maxhp()*def.value:def.value;if(resource==='hp'&&hasKey('ember'))amount*=.5;p[resource]=Math.min(max,p[resource]+amount);}}))return false;
 burst(p.x,p.y,65,def.color);playSound('heal',p.x,p.y);say(def.name+'を使用');return true;
}
heal=()=>drinkPotion(0);
cupFlaskMode=()=>!!(started&&p&&POTIONS[p.potionSlots?.[0]]?.kind==='hp'&&p.hp>=maxhp()&&hasStarBoon(namedBoonIndices.Crt));
phoenixFlaskMode=()=>!!(started&&p&&p.potions&&potionPhoenix(0));
function advancePotions(dt){ensurePotions();if(!p)return;if(dead){p.potionBuffs={};return;}if(!started||paused||!Number.isFinite(dt)||dt<=0)return;for(const field of ['potionCooldowns','potionBuffs'])for(const id of Object.keys(p[field]||{}))p[field][id]=Math.max(0,p[field][id]-dt);}
const potionUpdateBase=update;update=dt=>{ensurePotions();const running=started&&!paused;potionUpdateBase(dt);if(running||dead)advancePotions(dt);};
function potionIcon(id){const d=POTIONS[id];return '<svg class="potion-icon" viewBox="0 0 64 64" aria-hidden="true" style="color:'+d.color+'"><path d="M24 6H40V17L48 29V51Q48 58 40 58H24Q16 58 16 51V29L24 17Z" fill="#18252d" stroke="currentColor" stroke-width="3"/><path d="M19 34Q32 29 45 34V50Q45 55 39 55H25Q19 55 19 50Z" fill="currentColor" opacity=".8"/><path d="M23 9H41M24 18H40" stroke="#d9c796" stroke-width="4"/><text x="32" y="47" text-anchor="middle" fill="#0a1520" font-size="12" font-weight="bold">'+(d.kind==='buff'?{attack:'剣',guard:'盾',speed:'速',crit:'会',spell:'魔',stamina:'活'}[id]:d.kind.toUpperCase())+'</text></svg>';}
function buyPotion(id,count){ensurePotions();const d=POTIONS[id];if(!started||!villageOpen||dead||!d||![1,5,10].includes(count)||(p.potions[id]||0)+count>9999||p.gold<d.price*count)return false;if(!worldTransaction(()=>{p.gold-=d.price*count;p.potions[id]=(p.potions[id]||0)+count;}))return false;showPotionShop();iconSelectEntry(id,true);return true;}
function equipPotion(slot,id){ensurePotions();if(!paused||!started||dead||!Number.isInteger(slot)||slot<0||slot>2||!POTIONS[id])return false;if(!worldTransaction(()=>p.potionSlots[slot]=id))return false;showPotionLoadout();return true;}
const POTION_LABELS=['Y / 1','ZL＋R / 2','ZL＋L / 3'];
function showPotionShop(){if(!started||!villageOpen||dead)return say('ポーションは村のショップで購入できます');ensurePotions();worldMenu('ポーションショップ · '+p.gold+' G','<p>購入する品を選択</p>','potionShop');makeIconBrowser('potionShop',Object.entries(POTIONS).map(([id,d])=>({key:id,label:d.name+' ×'+(p.potions[id]||0),icon:potionIcon(id),nodes:[loadoutNode('<p>'+d.desc+'</p><p>所持 ×'+(p.potions[id]||0)+' · 1個 '+d.price+' G</p><p>再使用 '+d.cool+'秒。同じ品の待ち時間は3枠で共有。</p>'),...[1,5,10].map(n=>{const b=loadoutAction(n+'個購入 · '+d.price*n+' G',()=>buyPotion(id,n));b.disabled=p.gold<d.price*n||(p.potions[id]||0)+n>9999;return b;}),loadoutAction('ポーションを設定',()=>showPotionLoadout())]})));}
function showPotionLoadout(slot=null){if(!started||dead)return;ensurePotions();worldMenu('ポーション設定','<p>使用する枠を選択</p>','potions');const entries=slot===null?p.potionSlots.map((id,i)=>({key:'slot'+i,label:POTION_LABELS[i],icon:potionIcon(id),nodes:[loadoutNode('<h3>'+POTIONS[id].name+'</h3><p>所持 ×'+(p.potions[id]||0)+'</p><p>'+POTIONS[id].desc+'</p>'),loadoutAction('この枠のポーションを選ぶ',()=>showPotionLoadout(i)),...(villageOpen?[loadoutAction('ショップで購入',()=>showPotionShop())]:[])]})):Object.entries(POTIONS).map(([id,d])=>({key:id,label:d.name+' ×'+(p.potions[id]||0),icon:potionIcon(id),nodes:[loadoutNode('<p>'+POTION_LABELS[slot]+' に設定</p><p>'+d.desc+'</p><p>所持 ×'+(p.potions[id]||0)+' · 再使用 '+d.cool+'秒</p>'),loadoutAction((p.potionSlots[slot]===id?'✓ 設定中 · ':'')+'このポーションを設定',()=>equipPotion(slot,id))]}));makeIconBrowser('potions'+(slot??''),entries);}
showPotionShop=menuWrapRoute(showPotionShop,'potionShop');showPotionLoadout=menuWrapRoute(showPotionLoadout,'potions');
const potionVillageBase=showVillage;showVillage=(...args)=>{const result=potionVillageBase(...args);if(menuSurface==='village'){const b=document.createElement('button');b.textContent='ポーションショップ';b.onclick=()=>showPotionShop();($('card').querySelector('.panel-body')||$('card')).append(b);}return result;};
const potionPanelBase=panel;panel=(kind,...args)=>{const result=potionPanelBase(kind,...args);if(['inventory','pause'].includes(kind)&&menuSurface===kind){const b=document.createElement('button');b.className='potion-settings-button';b.textContent='ポーション設定';b.onclick=()=>showPotionLoadout();($('card').querySelector('.panel-heading')||$('card')).append(b);}return result;};
const potionEntriesBase=combatLoadoutEntries;combatLoadoutEntries=()=>[...potionEntriesBase(),{key:'potions',label:'ポーション3枠',icon:potionIcon('hp0'),nodes:[loadoutNode('<p>Y・ZL＋R・ZL＋Lで使用する品を設定します。</p>'),loadoutAction('ポーションを設定',()=>showPotionLoadout())]}];
for(let i=1;i<3;i++){const b=document.createElement('button');b.className='potion-quick';b.dataset.potionSlot=i;b.onclick=()=>drinkPotion(i);b.innerHTML='<kbd></kbd><strong></strong><small></small>';document.querySelector('footer .actions').append(b);}
const potionEffects=document.createElement('div');potionEffects.id='potionEffects';document.querySelector('.belt').prepend(potionEffects);
const potionHudBase=drawHud;drawHud=()=>{potionHudBase();if(!p)return;ensurePotions();const buttons=[document.querySelector('footer .actions button[onclick="heal()"]'),...document.querySelectorAll('.potion-quick')];buttons.forEach((b,i)=>{if(!b)return;const id=p.potionSlots[i],d=POTIONS[id],remaining=p.potionCooldowns[id]||0,count=p.potions[id]||0;if(b.dataset.potionView!==id){b.dataset.potionView=id;b.innerHTML=potionIcon(id).replace('potion-icon','potion-icon bar-icon')+'<kbd></kbd><strong></strong><small'+(i===0?' id="flasks"':'')+'></small>';}hudText(b.querySelector('kbd'),POTION_LABELS[i]);hudText(b.querySelector('strong'),d.name);hudText(b.querySelector('small'),remaining>0?Math.ceil(remaining)+'秒':'×'+count);hudTitle(b,d.name+' · '+d.desc+' · 所持×'+count);hudAttribute(b,'aria-label',d.name+' '+POTION_LABELS[i]);b.classList.toggle('potion-wait',remaining>0);});const active=Object.entries(p.potionBuffs).filter(([id,t])=>t>0),key=active.map(([id,t])=>id+Math.ceil(t)).join('|');if(potionEffects.dataset.key!==key){potionEffects.dataset.key=key;potionEffects.innerHTML=active.map(([id,t])=>'<span title="'+POTIONS[id].desc+'">'+potionIcon(id)+'<b>'+Math.ceil(t)+'秒</b></span>').join('');}potionEffects.hidden=!active.length;};
addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.altKey||e.metaKey||/INPUT|TEXTAREA|SELECT/.test(e.target?.tagName||''))return;if(e.key==='2'||e.key==='3')drinkPotion(Number(e.key)-1);});
